58	/// スナップショットを取り、取得履歴と比較基準に記録する
59	fn take_snapshot(store: &Store, watch: &Watch, now: i64) -> Result<Value> {
60	    let snapshot = collector::take_snapshot(&watch.baseline.snapshot_collectors, now);
61	    let keep = watch.baseline.keep_good_snapshots;
62	    store.record_snapshot(&watch.name, now, &snapshot, keep)?;
63	    Ok(snapshot)
64	}
