66	pub fn check(config: &Config, paths: &Paths, force: bool) -> Result<()> {
67	    if !lock::hold_until_exit(&paths.lock_file())? {
68	        log::info!("another check is running; skipping");
69	        return Ok(());
70	    }
71	    let mut store = Store::open(&paths.db_file())?;
72	    let mut failures = 0;
73	    for watch in &config.watches {
74	        // 1 つの watch の失敗で他の監視を止めない
75	        if let Err(error) = check_watch(&mut store, paths, watch, force, now()) {
76	            failures += 1;
77	            log::error!("watch {}: {error:#}", watch.name);
78	        }
79	    }
80	
81	    logging::prune(
82	        &paths.logs_dir,
83	        config.general.log_retention_days,
84	        Local::now().date_naive(),
85	    )?;
86	    incident::prune(
87	        &paths.incidents_dir,
88	        config.general.incident_retention_days,
89	        now(),
90	    )?;
91	    if failures > 0 {
92	        bail!("{failures} watch(es) failed");
93	    }
94	    Ok(())
95	}
