97	fn check_watch(
98	    store: &mut Store,
99	    paths: &Paths,
100	    watch: &Watch,
101	    force: bool,
102	    now: i64,
103	) -> Result<()> {
104	    let mut state = store.load_state(&watch.name)?;
105	    if !force && !is_due(state.last_probe, now, watch.interval) {
106	        log::debug!("{}: interval has not elapsed", watch.name);
107	        return Ok(());
108	    }
109	
110	    let run = probe::run(&watch.probe, now);
111	    let mut metrics = run.metrics();
112	    let classification = match &run.processes {
113	        Some(processes) => {
114	            let classification = classify_processes(store, paths, watch, processes, &metrics, now)?;
115	            metrics.extend(classification.metrics.clone());
116	            Some(classification)
117	        }
118	        None => None,
119	    };
120	    log_run(watch, &run, &metrics);
121	
122	    let stats = baseline::stats(store, &watch.name, &watch.baseline, now)?;
123	    let mut variables = metrics.clone();
124	    variables.extend(baseline::variables(&stats));
125	    let matched = trigger_matches(watch, &variables);
126	
127	    store.record_run(&watch.name, &run)?;
128	    if let Some(classification) = &classification {
129	        classification.record(store, &watch.name, now)?;
130	    }
131	    let retention = watch.baseline.metrics_retention.as_secs() as i64;
132	    store.prune_metrics(&watch.name, now - retention)?;
133	    state.last_probe = Some(now);
134	
135	    // 異常時の値でベースラインと last_known_good を汚さない
136	    let healthy = !matched && metrics["loss"] < 1.0;
137	    if healthy {
138	        baseline::update(store, &watch.name, &watch.baseline, &metrics, now)?;
139	        if is_snapshot_due(&state, now, watch.baseline.snapshot_interval)
140	            && !watch.baseline.snapshot_collectors.is_empty()
141	        {
142	            take_snapshot(store, watch, now)?;
143	        }
144	    }
145	
146	    let Some(trigger) = &watch.trigger else {
147	        store.save_state(&watch.name, &state)?;
148	        return Ok(());
149	    };
150	    let since = state.trigger.since;
151	    let outcome = trigger::advance(&mut state.trigger, matched, trigger, now);
152	    // 発火の処理で失敗しても二重に発火しないよう、先に状態を保存する
153	    store.save_state(&watch.name, &state)?;
154	    log::debug!("{}: trigger outcome {outcome:?}", watch.name);
155	
156	    match outcome {
157	        Outcome::Fired => {
158	            let since = state.trigger.since.unwrap_or(now);
159	            let reason = format!(
160	                "{} が {} 回連続で成立",
161	                trigger.when.source(),
162	                state.trigger.streak
163	            );
164	            let pending = classification
165	                .as_ref()
166	                .map(Classification::pending_identities)
167	                .unwrap_or_default();
168	            fire(store, paths, watch, &run, &stats, since, &reason, &pending)
169	        }
170	        Outcome::Suppressed => {
171	            log::info!("{}: in cooldown, not firing", watch.name);
172	            Ok(())
173	        }
174	        Outcome::Recovered if trigger.recover_notify => {
175	            write_recovery(paths, &watch.name, since.unwrap_or(now), now)
176	        }
177	        Outcome::Recovered => {
178	            log::info!("{}: recovered", watch.name);
179	            Ok(())
180	        }
181	        Outcome::Normal | Outcome::Pending => Ok(()),
182	    }
183	}
