185	fn log_run(watch: &Watch, run: &ProbeRun, metrics: &Variables) {
186	    log::info!("{}: {metrics:?}", watch.name);
187	    for result in &run.results {
188	        log::debug!(
189	            "{}: {} ok={} rtt_ms={:?} error={:?}",
190	            watch.name,
191	            result.target,
192	            result.ok,
193	            result.rtt_ms,
194	            result.error
195	        );
196	    }
197	}
