199	fn build_incident(
200	    store: &Store,
201	    paths: &Paths,
202	    watch: &Watch,
203	    run: &ProbeRun,
204	    stats: &[SeriesStats],
205	    since: i64,
206	    reason: &str,
207	) -> Result<Incident> {
208	    let created = now();
209	    let current = collector::take_snapshot(&watch.baseline.snapshot_collectors, created);
210	    let collectors: Vec<String> = watch
211	        .baseline
212	        .snapshot_collectors
213	        .iter()
214	        .map(|spec| spec.name())
215	        .collect();
216	    let last_good = store.last_known_good(&watch.name, &collectors)?;
217	    let history = store.recent_metrics(&watch.name, INCIDENT_HISTORY_RUNS)?;
218	    let evidence = Evidence {
219	        watch: &watch.name,
220	        reason,
221	        since,
222	        run,
223	        stats,
224	        history: &history,
225	        current: &current,
226	        last_good: last_good.as_ref(),
227	    };
228	    incident::create(&paths.incidents_dir, &evidence, created)
229	}
