231	fn register_investigation(paths: &Paths, watch: &str) -> Option<investigation::Registration> {
232	    let result =
233	        probe::enumerate().and_then(|processes| investigation::register(paths, watch, &processes));
234	    result.unwrap_or_else(|error| {
235	        log::warn!("{watch}: could not record the investigation: {error:#}");
236	        None
237	    })
