279	fn fire(
280	    store: &mut Store,
281	    paths: &Paths,
282	    watch: &Watch,
283	    run: &ProbeRun,
284	    stats: &[SeriesStats],
285	    since: i64,
286	    reason: &str,
287	    pending: &[String],
288	) -> Result<()> {
289	    let incident = build_incident(store, paths, watch, run, stats, since, reason)?;
290	    log::warn!(
291	        "{}: fired ({reason}); incident {}",
292	        watch.name,
293	        incident.dir.display()
294	    );
295	    // 事件に含めた分は報告済みにする。同じプロセスでは、クールダウンが明けても再発火しない
296	    store.mark_reported(&watch.name, pending)?;
297	    if watch.diagnose.is_some() {
298	        detach::spawn_diagnose(&watch.name, &incident.dir)?;
299	    }
300	    Ok(())
301	}
