303	fn write_recovery(paths: &Paths, watch: &str, since: i64, now: i64) -> Result<()> {
304	    let dir = paths.reports_dir.join(watch);
305	    create_private_dir(&dir)?;
306	    let stamp = Local::now().format("%Y%m%d-%H%M%S");
307	    let path = dir.join(format!("{stamp}-recovered.md"));
308	    let text = format!(
309	        "# 回復: {watch}\n\n- 発生開始: {}\n- 回復確認: {}\n",
310	        format_time(since),
311	        format_time(now)
312	    );
313	    std::fs::write(&path, text).with_context(|| format!("failed to write {}", path.display()))?;
314	    log::info!("{watch}: recovered; {}", path.display());
315	    Ok(())
316	}
