318	pub fn snapshot(config: &Config, paths: &Paths, force: bool, only: Option<&str>) -> Result<()> {
319	    if let Some(name) = only {
320	        config.watch(name)?;
321	    }
322	    let store = Store::open(&paths.db_file())?;
323	    let mut failed = 0;
324	    let selected = config
325	        .watches
326	        .iter()
327	        .filter(|watch| only.is_none_or(|name| name == watch.name));
328	    for watch in selected {
329	        let collectors = &watch.baseline.snapshot_collectors;
330	        if collectors.is_empty() {
331	            println!("{}: no snapshot_collectors configured", watch.name);
332	            continue;
333	        }
334	        // check のロックは取らない。check と並行してよいよう、スナップショットの記録以外は
335	        // 書かない。ここで読んだ状態を save_state で書き戻すと、収集中に check が保存した状態を巻き戻す
336	        let state = store.load_state(&watch.name)?;
337	        let now = now();
338	        if !force && !is_snapshot_due(&state, now, watch.baseline.snapshot_interval) {
339	            println!(
340	                "{}: not due yet (snapshot_interval, or the retry interval after a failure)",
341	                watch.name
342	            );
343	            continue;
344	        }
345	        let snapshot = take_snapshot(&store, watch, now)?;
346	        print_collectors(&watch.name, &snapshot);
347	        failed += collector::failed_collectors(&snapshot).len();
348	    }
349	    if failed > 0 {
350	        bail!("{failed} collector(s) failed");
351	    }
352	    Ok(())
353	}
