355	fn print_collectors(watch: &str, snapshot: &Value) {
356	    let collectors = snapshot["collectors"].as_object().into_iter().flatten();
357	    for (name, result) in collectors {
358	        match result["error"].as_str() {
359	            None => println!("{watch}: {name}: ok"),
360	            Some(error) => println!("{watch}: {name}: FAILED: {error}"),
361	        }
362	    }
363	}
