365	pub struct DiagnoseOptions {
366	    pub watch: String,
367	    pub dry_run: bool,
368	    pub backend: Option<String>,
369	    pub incident: Option<PathBuf>,
370	    pub notify: bool,
371	}
372	
373	pub fn diagnose(config: &Config, paths: &Paths, options: DiagnoseOptions) -> Result<()> {
374	    let watch = config.watch(&options.watch)?;
375	    let override_kind = options
376	        .backend
377	        .as_deref()
378	        .map(BackendKind::parse)
379	        .transpose()?;
380	
381	    let incident = match &options.incident {
382	        Some(dir) => incident::load(dir)?,
383	        None => manual_incident(paths, watch)?,
384	    };
385	    // 別の watch の事件を、この watch の設定やロックのまま調べない
386	    ensure!(
387	        incident.watch == watch.name,
388	        "incident {} belongs to watch {:?}, not {:?}",
389	        incident.dir.display(),
390	        incident.watch,
391	        watch.name
392	    );
393	    println!("incident: {}", incident.dir.display());
394	    if options.dry_run {
395	        return Ok(());
396	    }
397	
398	    let diagnose = watch
399	        .diagnose
400	        .as_ref()
401	        .with_context(|| format!("watch {} has no [watch.diagnose]", watch.name))?;
402	    let lock_path = paths
403	        .lock_dir
404	        .join(format!("kuda-diagnose-{}.lock", watch.name));
405	    if !lock::hold_until_exit(&lock_path)? {
406	        log::info!("{}: an investigation is already running", watch.name);
407	        println!("an investigation for {} is already running", watch.name);
408	        return Ok(());
409	    }
410	    // 調査の間だけ記録し、check のプロセス監視が調査プロセスを未知として数えないようにする
411	    let _registration = register_investigation(paths, &watch.name);
412	    let notify = options.notify && config.general.notify;
413	    if notify {
414	        notify::send(&Event::Started { watch: &watch.name });
415	    }
416	    let result = diagnosis::investigate(config, paths, diagnose, &incident, override_kind);
417	    if notify {
418	        let failed_report = diagnosis::report_path(paths, &incident).ok();
419	        notify::send(&match &result {
420	            Ok(report) => Event::Finished {
421	                watch: &watch.name,
422	                report,
423	            },
424	            Err(_) => Event::Failed {
425	                watch: &watch.name,
426	                report: failed_report.as_deref().filter(|path| path.is_file()),
427	            },
428	        });
429	    }
430	    let report = result?;
431	    log::info!("{}: report {}", watch.name, report.display());
432	    println!("report: {}", report.display());
433	    Ok(())
434	}
