460	/// 最後の取得時刻と、そのとき失敗した collector があったか。
461	/// 成否の記録が無いとき（版 3 へ上げた直後）は、失敗とは言い切らない
462	fn snapshot_status(state: &WatchState) -> String {
463	    let Some(last) = state.last_snapshot else {
464	        return "none".to_string();
465	    };
466	    match state.last_snapshot_complete {
467	        Some(true) => format_time(last),
468	        Some(false) => format!(
469	            "{} (some collectors failed; last complete: {})",
470	            format_time(last),
471	            state
472	                .last_complete_snapshot
473	                .map_or("none".to_string(), format_time)
474	        ),
475	        None => format!("{} (no complete snapshot recorded yet)", format_time(last)),
476	    }
477	}
