479	fn print_probe_status(store: &Store, watch: &Watch, state: &WatchState) -> Result<()> {
480	    let last_probe = state.last_probe.map_or("never".to_string(), format_time);
481	    println!("  last probe: {last_probe}");
482	    println!("  samples: {}", store.sample_count(&watch.name)?);
483	    for result in store.last_results(&watch.name)? {
484	        let outcome = match (&result.error, result.rtt_ms) {
485	            (Some(error), _) => format!("FAILED: {error}"),
486	            (None, Some(rtt)) => format!("ok ({rtt:.1} ms)"),
487	            (None, None) => "ok".to_string(),
488	        };
489	        println!("    {}: {outcome}", result.target);
490	    }
491	    Ok(())
492	}
