494	fn print_baseline(stats: &[SeriesStats]) {
495	    if stats.is_empty() {
496	        println!("  baseline: not enough samples yet");
497	    }
498	    for stat in stats {
499	        let source = match stat.source {
500	            Source::Bucket => "this time slot",
501	            Source::Overall => "overall",
502	        };
503	        println!(
504	            "  baseline {}: p50={:.3} p95={:.3} ({source}, {} samples)",
505	            stat.series, stat.p50, stat.p95, stat.samples
506	        );
507	    }
508	}
