510	fn print_trigger_status(watch: &Watch, state: &WatchState, now: i64) {
511	    let Some(trigger) = &watch.trigger else {
512	        println!("  trigger: none");
513	        return;
514	    };
515	    let cooldown = trigger.cooldown.as_secs() as i64;
516	    let remaining = state
517	        .trigger
518	        .last_fired
519	        .map_or(0, |fired| fired + cooldown - now)
520	        .max(0);
521	    println!(
522	        "  trigger: streak {}/{}, {}, cooldown remaining {remaining}s",
523	        state.trigger.streak,
524	        trigger.consecutive,
525	        if state.trigger.active {
526	            "active"
527	        } else {
528	            "idle"
529	        },
530	    );
531	}
