533	pub fn check_config(config: &Config, paths: &Paths) -> Result<()> {
534	    let mut problems = Vec::new();
535	    for watch in &config.watches {
536	        let Some(diagnose) = &watch.diagnose else {
537	            continue;
538	        };
539	        let prompt = paths.config_dir.join(&diagnose.prompt_file);
540	        if !prompt.is_file() {
541	            problems.push(format!(
542	                "{}: prompt file not found: {}",
543	                watch.name,
544	                prompt.display()
545	            ));
546	        }
547	        for kind in std::iter::once(diagnose.backend).chain(diagnose.fallback) {
548	            if let Some(command) = backend_command(config, kind)
549	                && exec::find_program(command).is_none()
550	            {
551	                problems.push(format!(
552	                    "{}: {} command not found: {command}",
553	                    watch.name,
554	                    kind.name()
555	                ));
556	            }
557	        }
558	    }
559	    if !problems.is_empty() {
560	        for problem in &problems {
561	            println!("{problem}");
562	        }
563	        bail!("{} problem(s) found", problems.len());
564	    }
565	    println!("config ok: {} watch(es)", config.watches.len());
566	    Ok(())
567	}
