569	/// ローカル LLM はサーバーが常駐とは限らないので、ここでは調べない
570	fn backend_command(config: &Config, kind: BackendKind) -> Option<&str> {
571	    match kind {
572	        BackendKind::ClaudeCode => Some(&config.backends.claude_code.as_ref()?.command),
573	        BackendKind::Codex => Some(&config.backends.codex.as_ref()?.command),
