33	/// スケジューラの起動はぴったり interval おきとは限らない。わずかに早い起動で
34	/// 1 周まるごと飛ばさないよう、interval の 1 割（最大 30 秒）の早まりを許す
35	fn is_due(last: Option<i64>, now: i64, interval: Duration) -> bool {
36	    let Some(last) = last else {
37	        return true;
38	    };
39	    let interval = interval.as_secs() as i64;
40	    now - last >= interval - (interval / 10).min(30)
41	}
42	
43	/// collector が失敗した取得の後は、snapshot_interval を待たずにこの間隔で取り直す
44	const SNAPSHOT_RETRY_INTERVAL: Duration = Duration::from_secs(30 * 60);
45	
46	/// スナップショットを取る時期か。最後の取得で全 collector が成功していれば snapshot_interval、
47	/// 失敗した collector があれば再試行の間隔（snapshot_interval が短ければそちら）を、
48	/// 最後の取得から空ける
49	fn is_snapshot_due(state: &WatchState, now: i64, interval: Duration) -> bool {
50	    let wait = if state.last_snapshot_complete == Some(true) {
51	        interval
52	    } else {
53	        interval.min(SNAPSHOT_RETRY_INTERVAL)
54	    };
55	    is_due(state.last_snapshot, now, wait)
56	}
57	
58	/// スナップショットを取り、取得履歴と比較基準に記録する
59	fn take_snapshot(store: &Store, watch: &Watch, now: i64) -> Result<Value> {
60	    let snapshot = collector::take_snapshot(&watch.baseline.snapshot_collectors, now);
61	    let keep = watch.baseline.keep_good_snapshots;
62	    store.record_snapshot(&watch.name, now, &snapshot, keep)?;
63	    Ok(snapshot)
64	}
