247	/// プロセスを既知の集合と照らして分類する。
248	///
249	/// 学習してよいのは正常な回だけ。正常かどうかは条件式の成否で決まるが、その式の変数は
250	/// 分類の結果に依存する。そこで、まず学習する前提で分類し、式が成立したら（異常なら）
251	/// 何も学習しない前提でやり直す。やり直すと pending が増えるだけなので、成立したままになる
252	fn classify_processes(
253	    store: &Store,
254	    paths: &Paths,
255	    watch: &Watch,
256	    processes: &[ProcessInfo],
257	    metrics: &Variables,
258	    now: i64,
259	) -> Result<Classification> {
260	    let roots = Roots::from_env();
261	    // kuda 自身と、実行中の調査プロセス（detach されていて親子ではたどれない）
262	    let mut excluded: Vec<_> = known_set::own_root(processes).into_iter().collect();
263	    excluded.extend(investigation::running(paths, processes));
264	    let classify =
265	        |learn| known_set::classify(store, watch, processes, &excluded, &roots, now, learn);
266	    let classification = classify(true)?;
267	    if classification.learned == 0 {
268	        return Ok(classification);
269	    }
270	    let mut variables = metrics.clone();
271	    variables.extend(classification.metrics.clone());
272	    if trigger_matches(watch, &variables) {
273	        return classify(false);
274	    }
275	    Ok(classification)
276	}
