43	impl TargetResult {
44	    fn new(target: &str, result: Result<Sample, String>) -> Self {
45	        let (sample, error) = match result {
46	            Ok(sample) => (Some(sample), None),
47	            Err(error) => (None, Some(error)),
48	        };
