90	/// create_unique_dir が付ける形の id（時刻と連番）か。英字を通さないので
91	/// `-recovered` の回復レポートや Windows の予約名（NUL など）と重ならない
92	fn is_incident_id(id: &str) -> bool {
93	    !id.is_empty() && id.chars().all(|c| c.is_ascii_digit() || c == '-')
94	}
95	
96	pub fn load(dir: &Path) -> Result<Incident> {
97	    let path = dir.join(META_FILE);
98	    let text = std::fs::read_to_string(&path)
99	        .with_context(|| format!("failed to read {}", path.display()))?;
100	    let mut incident: Incident = serde_json::from_str(&text)?;
101	    // watch と id はレポートの保存先パスに使う。他人から受け取った事件でも外へ書かせない
102	    ensure!(
103	        is_safe_name(&incident.watch),
104	        "{} has an invalid watch: {:?}",
105	        path.display(),
106	        incident.watch
107	    );
108	    ensure!(
109	        is_incident_id(&incident.id),
110	        "{} has an invalid id: {:?}",
111	        path.display(),
112	        incident.id
113	    );
114	    incident.dir = dir.to_path_buf();
115	    Ok(incident)
116	}
117	
118	/// 保持期間を過ぎた事件ディレクトリを削除する
119	pub fn prune(incidents_dir: &Path, retention_days: u32, now: i64) -> Result<()> {
120	    let cutoff = now - i64::from(retention_days) * 86400;
121	    for watch_dir in std::fs::read_dir(incidents_dir)? {
122	        let watch_dir = watch_dir?.path();
123	        if !watch_dir.is_dir() {
124	            continue;
125	        }
126	        for entry in std::fs::read_dir(&watch_dir)? {
127	            let dir = entry?.path();
128	            if load(&dir).is_ok_and(|incident| incident.created < cutoff) {
129	                std::fs::remove_dir_all(&dir)
130	                    .with_context(|| format!("failed to remove {}", dir.display()))?;
131	            }
132	        }
133	    }
134	    Ok(())
135	}
