313	/// 1 回の probe で報告対象（pending）になった識別キーと、その代表のプロセス
314	#[derive(Debug, Clone, PartialEq)]
315	pub struct PendingProcess {
316	    pub identity: Identity,
317	    /// 同じ識別キーのプロセスのうち、PID が最小のもの
318	    pub process: ProcessInfo,
