323	/// 分類の結果。ストアには `record` を呼ぶまで書かない
324	/// （異常と判定されたとき、学習しない形でやり直すため）
325	#[derive(Debug, Clone, PartialEq)]
326	pub struct Classification {
327	    /// unknown / unknown_user_writable / masquerade / missing / process_count
328	    pub metrics: Variables,
329	    /// 今 動いている pending。事件の証拠にする
330	    pub pending: Vec<PendingProcess>,
331	    /// 新しく known として登録する識別キーの数
332	    pub learned: usize,
333	    /// 今回見た識別キーと、新規のときに登録する status
334	    seen: Vec<(String, IdentityStatus)>,
335	}
