337	impl Classification {
338	    pub fn pending_identities(&self) -> Vec<String> {
339	        self.pending
340	            .iter()
341	            .map(|p| p.identity.key.clone())
342	            .collect()
343	    }
344	
345	    /// 今回見た識別キーを記録する。学習期間の起点もここで決まる
346	    pub fn record(&self, store: &mut Store, watch: &str, now: i64) -> Result<()> {
347	        store.start_learning(watch, now)?;
348	        store.observe_identities(watch, now, &self.seen)
349	    }
350	}
351	
352	/// 識別キーごとにまとめた、今 動いているプロセス
353	struct Observed<'a> {
354	    identity: Identity,
355	    process: &'a ProcessInfo,
356	    user_writable: bool,
357	    masquerade: bool,
358	}
359	
360	/// 動いているプロセスを既知の集合と照らして分類する。ストアは読むだけ。
361	///
362	/// `learn` が true で学習期間中なら、新しく見た識別キーを known にする（masquerade を除く）。
363	/// それ以外の新しい識別キーは pending にする。`excluded` は kuda 自身と調査プロセスの根
364	pub fn classify(
365	    store: &Store,
366	    watch: &Watch,
367	    processes: &[ProcessInfo],
368	    excluded: &[(u32, i64)],
369	    roots: &Roots,
370	    now: i64,
371	    learn: bool,
372	) -> Result<Classification> {
373	    let os = roots.os;
374	    let probe = &watch.probe;
375	    let mut observed: BTreeMap<String, Observed> = BTreeMap::new();
376	    for process in without_descendants(processes, excluded) {
377	        let Some(identity) = identify(os, process) else {
378	            continue;
379	        };
380	        if probe.ignore.iter().any(|g| glob_match(g, &identity.key)) {
381	            continue;
382	        }
383	        let path = process.path.as_deref();
384	        let masquerade = is_masquerade(roots, &process.name, path);
385	        let user_writable = path.is_some_and(|p| is_user_writable(roots, p));
386	        let entry = observed
387	            .entry(identity.key.clone())
388	            .or_insert_with(|| Observed {
389	                identity,
390	                process,
391	                user_writable,
392	                masquerade,
393	            });
394	        // 代表は PID が最小のもの。列挙の順序に結果を依存させない
