96	pub fn load(dir: &Path) -> Result<Incident> {
97	    let path = dir.join(META_FILE);
98	    let text = std::fs::read_to_string(&path)
99	        .with_context(|| format!("failed to read {}", path.display()))?;
100	    let mut incident: Incident = serde_json::from_str(&text)?;
101	    // watch と id はレポートの保存先パスに使う。他人から受け取った事件でも外へ書かせない
102	    ensure!(
103	        is_safe_name(&incident.watch),
104	        "{} has an invalid watch: {:?}",
105	        path.display(),
106	        incident.watch
107	    );
108	    ensure!(
109	        is_incident_id(&incident.id),
110	        "{} has an invalid id: {:?}",
111	        path.display(),
112	        incident.id
113	    );
114	    incident.dir = dir.to_path_buf();
115	    Ok(incident)
116	}
