352	/// 識別キーごとにまとめた、今 動いているプロセス
353	struct Observed<'a> {
354	    identity: Identity,
355	    process: &'a ProcessInfo,
356	    user_writable: bool,
357	    masquerade: bool,
358	}
359	
360	/// 動いているプロセスを既知の集合と照らして分類する。ストアは読むだけ。
361	///
362	/// `learn` が true で学習期間中なら、新しく見た識別キーを known にする（masquerade を除く）。
363	/// それ以外の新しい識別キーは pending にする。`excluded` は kuda 自身と調査プロセスの根
364	pub fn classify(
365	    store: &Store,
366	    watch: &Watch,
367	    processes: &[ProcessInfo],
368	    excluded: &[(u32, i64)],
369	    roots: &Roots,
370	    now: i64,
371	    learn: bool,
372	) -> Result<Classification> {
373	    let os = roots.os;
374	    let probe = &watch.probe;
375	    let mut observed: BTreeMap<String, Observed> = BTreeMap::new();
376	    for process in without_descendants(processes, excluded) {
377	        let Some(identity) = identify(os, process) else {
378	            continue;
379	        };
380	        if probe.ignore.iter().any(|g| glob_match(g, &identity.key)) {
381	            continue;
382	        }
383	        let path = process.path.as_deref();
384	        let masquerade = is_masquerade(roots, &process.name, path);
385	        let user_writable = path.is_some_and(|p| is_user_writable(roots, p));
386	        let entry = observed
387	            .entry(identity.key.clone())
388	            .or_insert_with(|| Observed {
389	                identity,
390	                process,
391	                user_writable,
392	                masquerade,
393	            });
394	        // 代表は PID が最小のもの。列挙の順序に結果を依存させない
395	        if process.pid < entry.process.pid {
396	            entry.process = process;
397	        }
398	        entry.masquerade |= masquerade;
399	    }
400	
401	    let started = store.learning_started(&watch.name)?.unwrap_or(now);
402	    let learning = watch
403	        .baseline
404	        .learn_for
405	        .is_some_and(|d| now < started.saturating_add(d.as_secs() as i64));
406	    let statuses = store.identity_statuses(&watch.name)?;
407	
408	    let mut seen = Vec::new();
409	    let mut pending = Vec::new();
410	    let mut learned = 0;
411	    for (key, o) in &observed {
412	        let status = match statuses.get(key) {
413	            Some(status) => *status,
414	            // 偽装は、学習期間中でも正常として覚えない
415	            None if learn && learning && !o.masquerade => {
416	                learned += 1;
417	                IdentityStatus::Known
418	            }
419	            None => IdentityStatus::Pending,
420	        };
421	        seen.push((key.clone(), status));
422	        if status == IdentityStatus::Pending {
423	            pending.push(PendingProcess {
424	                identity: o.identity.clone(),
425	                process: o.process.clone(),
426	                user_writable: o.user_writable,
427	                masquerade: o.masquerade,
428	            });
429	        }
430	    }
431	
432	    let count = |f: fn(&PendingProcess) -> bool| pending.iter().filter(|p| f(p)).count() as f64;
433	    let missing = probe
434	        .expected
435	        .iter()
436	        .filter(|g| !observed.keys().any(|key| glob_match(g, key)))
437	        .count();
438	    let mut metrics = Variables::new();
439	    metrics.insert("unknown".to_string(), pending.len() as f64);
440	    metrics.insert(
441	        "unknown_user_writable".to_string(),
442	        count(|p| p.user_writable),
443	    );
444	    metrics.insert("masquerade".to_string(), count(|p| p.masquerade));
445	    metrics.insert("missing".to_string(), missing as f64);
446	    metrics.insert("process_count".to_string(), observed.len() as f64);
447	    Ok(Classification {
448	        metrics,
449	        pending,
450	        learned,
451	        seen,
452	    })
453	}
